uda=True):\n45:     \"\"\"Validate the complete public input domain; also usable on CPU.\"\"\"\n46:     def require(condition, message):\n47:         if not condition:\n48:             raise ValueError(message)\n49: \n50:     require(not torch.is_inference_mode_enabled(), \"ordinary execution mode required\")\n51:     require(type(x) is torch.Tensor, \"ordinary torch.Tensor required\")\n52:     require(x.layout == torch.strided and x.is_contiguous(),\n53:             \"contiguous strided input required\")\n54:     require(not x.requires_grad and not x.is_inference(),\n55:             \"ordinary non-gradient input required\")\n56:     require(not x.is_neg() and not x.is_conj(),\n57:             \"logical view flags are outside this domain\")\n58:     require(not require_cuda or x.is_cuda, \"CUDA input required by run\")\n59:     require(x.ndim == 1 and 1 <= x.numel() <= 131072,\n60:             \"x must have shape [N] with N in [1,131072]\")\n61:     require(x.dtype == torch.float16, \"FP16 input required\")\n62:     require(bool(torch.isfinite(x).all().item()), \"all input values must be finite\")\n63:     return {\"valid\": True, \"size\": x.numel()}\n64: \n65: \n66: def run(x):\n67:     \"\"\"Return a fresh FP32 tensor approximating atan of each stored input value.\"\"\"\n68:     validate_inputs(x)\n69:     n = x.numel()\n70:     with torch.cuda.device(x.device):\n71:         output = torch.empty((n,), dtype=torch.float32, device=x.device)\n72:         _atan_kernel[(triton.cdiv(n, 256),)](\n73:             x, output, N=n, BLOCK=256, num_warps=4, enable_fp_fusion=False)\n74:     return output\n75: \n76: \n77: def reference(x):\n78:     \"\"\"Evaluate mathematical atan independently using the FP64 library function.\"\"\"\n79:     validate_inputs(x, require_cuda=False)\n80:     return torch.atan(x.to(torch.float64))\n81: \n82: \n83: def make_inputs(device=\"cuda\", size=4093, seed=0):\n84:     \"\"\"Convenience example generator, not a restriction on the input domain